from cpu_diagnostics_common import *
import statistics

def group_mean(rows,keys,values):
 groups={}
 for r in rows:groups.setdefault(tuple(r[k] for k in keys),[]).append(r)
 return [dict(zip(keys,key),**{k:float(np.mean([float(r[k]) for r in rr if r.get(k) not in ['',None]])) if any(r.get(k) not in ['',None] for r in rr) else None for k in values},seed_count=len(rr)) for key,rr in groups.items()]

def main():
 for phase in ['audit','physics','adaptive_offline','mhw_statistics','climatology']:assert json.loads((OUT/(phase+'_status.json')).read_text())['status']=='PASS',phase
 cum=readcsv(OUT/'cumulative_physics.csv');rel=readcsv(OUT/'residual_error_relationship.csv');strata=readcsv(OUT/'residual_error_strata.csv');mhw=readcsv(OUT/'mhw_group_errors.csv');trans=readcsv(OUT/'mhw_transitions.csv');grad=readcsv(OUT/'adaptive_offline_summary.csv');cov=readcsv(OUT/'climatology_coverage.csv');rough=readcsv(OUT/'climatology_roughness.csv');anom=readcsv(OUT/'anomaly_distributions.csv');holm=readcsv(OUT/'sst_holm.csv');mb=readcsv(OUT/'mhw_bootstrap.csv')
 primary=group_mean([r for r in cum if r['region']=='all' and r['season']=='all' and r['mode']=='linear_observed_learned_we'],['ratio','lead','split'],['rmse_K','zero_rhs_rmse_K','rmse_skill_vs_zero','rmse_per_day','pearson','daily_residual_rmse_Kday','cancellation_ratio'])
 allmodes=group_mean([r for r in cum if r['region']=='all' and r['season']=='all'],['ratio','lead','split','mode'],['rmse_K','zero_rhs_rmse_K','rmse_skill_vs_zero','rmse_per_day','pearson','daily_residual_rmse_Kday','cancellation_ratio'])
 relation=group_mean([r for r in rel if r['mode']=='linear_observed_learned_we'],['ratio','lead','split'],['day_corr_residual_vs_pinn_rmse','day_corr_residual_vs_delta_mse','cell_corr_residual_vs_delta_mse','pooled_corr_abs_residual_vs_delta_se'])
 strata_summary=group_mean([r for r in strata if r['mode']=='linear_observed_learned_we'],['ratio','lead','split','region','season','top_fraction'],['baseline_rmse','physics_rmse','improvement_percent','delta_mse'])
 mhwsum=group_mean(mhw,['ratio','lead','model','group'],['rmse','bias','threshold_distance_mean','pred_below_threshold_fraction'])
 transition_summary=group_mean(trans,['ratio','lead','event_transition'],['n','near_threshold_abs025K_fraction','pinn_minus_baseline_temperature_K','baseline_bias','physics_bias','observed_threshold_distance'])
 csvsave('mhw_transition_summary.csv',transition_summary)
 adsum=group_mean(grad,['ratio','lead','state','rho','mode'],['lambda_median','upper_clamp_fraction','lower_clamp_fraction','greater_than_fixed_fraction','effective_ratio_median','conflict_fraction'])
 coverage=group_mean(cov,['ratio'],['unique_input_days','empty_doy','empty_fraction','singleton_doy','singleton_fraction','feb29_count'])
 rs=group_mean(rough,['ratio','variable'],['climatology_daystep_rms','climatology_daystep_abs_p95','climatology_daystep_abs_max','singleton_training_date_fraction'])
 aa=group_mean(anom,['ratio','lead','split','variable'],['raw_std','anomaly_std','history_weighted_anomaly_std','unique_z_std','history_z_std','anomaly_variance_to_raw'])
 for name,rows in [('cumulative_summary.csv',primary),('cumulative_modes_summary.csv',allmodes),('relationship_summary.csv',relation),('strata_summary.csv',strata_summary),('mhw_error_summary.csv',mhwsum),('adaptive_summary.csv',adsum),('coverage_summary.csv',coverage),('roughness_summary.csv',rs),('anomaly_summary.csv',aa)]:csvsave(name,rows)
 # Matched endpoint dates provide direct7/14 normalized residual comparisons.
 matched=[]
 for ratio in RATIOS:
  for seed in SEEDS:
   for split in ['train','val','test']:
    with np.load(OUT/'fields'/f'physics_r{ratio}_l7_s{seed}_{split}.npz') as z7,np.load(OUT/'fields'/f'physics_r{ratio}_l14_s{seed}_{split}.npz') as z14:
     idx,i7,i14=np.intersect1d(z7['target_index'],z14['target_index'],return_indices=True)
     row=dict(ratio=ratio,seed=seed,split=split,matched_target_dates=len(idx))
     for lead,z,ix in [(7,z7,i7),(14,z14,i14)]:
      resid=z['linear_observed_learned_we_cumulative_residual_K'][ix].astype(float);obs=z['observed_delta_K'][ix].astype(float);rr=np.sqrt((resid**2).mean());zero=np.sqrt((obs**2).mean());row.update({f'lead{lead}_rmse_per_day':rr/lead,f'lead{lead}_skill_vs_zero':1-rr/zero,f'lead{lead}_rmse_K':rr})
     matched.append(row)
 csvsave('matched_lead_cumulative.csv',matched)
 # Validate prior6-case primary daily residual statistics against new aggregation.
 prior=readcsv(ADAPT/'observed_residual_summary.csv');reg=[]
 for r in prior:
  if r['mode']!='native_linear_checkpoint_we' or r['group']!='all':continue
  x=next(x for x in cum if all(x[k]==r[k] for k in ['ratio','lead','seed']) and x['split']=='train' and x['mode']=='linear_observed_learned_we' and x['region']=='all' and x['season']=='all')
  error=abs(float(x['daily_residual_rmse_Kday'])-float(r['residual_rmse']));assert error<2e-5;reg.append(dict(ratio=r['ratio'],lead=r['lead'],seed=r['seed'],absolute_error=error))
 save(OUT/'prior_residual_regression.json',dict(status='PASS',rows=reg))
 # Final preservation check over every audited input, including native source/raw/checkpoints.
 hashes=json.loads((OUT/'protected_input_hashes.json').read_text())
 for path,expected in hashes.items():assert sha(path)==expected,path
 assert json.loads((ADAPT/'user_pause.json').read_text())['supervisor_stopped']
 test=[r for r in primary if r['split']=='test'];p90=[r for r in holm if r['block_days']=='90'];bad=sum(r['rmse_skill_vs_zero']<0 for r in test)
 lines=['# CPU 전용 진단 최종 보고','',stamp(),'','기존 저장된 예측과 w_e만 사용했다. 신규 모델 추론/backward/학습, GPU 접근, 기존 전처리·checkpoint 변경이 없다. 24개 조건×Train/Validation/Test 누적 residual을 분석했다. Test 기반 분석은 탐색적이며 후속 성능을 확증하지 않는다. 수치 표의 평균은 별도 명시가 없으면3개 seed 통계의 산술평균이다.','', '## 1. 입력 감사와 실행 범위','', 'artifact_inventory.csv:144개 저장 예측 파일에 prediction/target/we/date/mask 존재. RHS 시계열은 저장되지 않았으므로 native _linear_rhs_per_day를 CPU에서 재평가했다. 기존 best checkpoint와 예측 해시가 연결됨을 검증했다. CPU2 threads,16GiB 주소공간 상한,단일 분석 worker. GPU 대기열 중지 유지.','', '## 2.7/14일 누적 Physics 적합성','', '관측 누적 변화 ΔT와 native 일별 RHS의 합(각1일)을 비교한다. 관측 endpoint를 사용한 선형 경로가 주 분석이고, 실제 관측 일별 경로/zero-we partial RHS/모델 예측 endpoint는 별도 mode이다. Learned we를 포함하므로 독립 관측 열수지가 아니다. 모든 계산은 clipping 전 raw residual. RHS 전체를 상수로 가정하지 않았다.','',table(test,['ratio','lead','rmse_K','zero_rhs_rmse_K','rmse_skill_vs_zero','rmse_per_day','pearson','cancellation_ratio']),'',f'Test8조건 중{bad}개에서 seed평균 cumulative skill이0보다 작았다. Skill=1−RMSEphysics/RMSEzero; 음수면 변화량0 기준보다 관측 누적 변화 설명이 나쁘다. 관측 endpoint가 RHS의 이류항에도 들어가므로 이는 직접 예측모델 성능 비교가 아닌 열수지 적합성 검사다.','', 'cumulative_modes_summary.csv에서 실제 일별 경로와 비교하고, matched_lead_cumulative.csv는 동일 endpoint 날짜·seed에서7/14일을 비교한다. 서로 다른 기간 길이·forcing 및 seed별 checkpoint 차이가 있으므로 lead 차이를 단일 원인으로 해석하지 않는다. 지역은 in-domain 육지에 인접한 해양 셀(coast proxy),나머지 offshore,외곽 domain edge로 정의했다. 격자별 경위도 결과는 physics_spatial.csv.','', '## 3.Residual–예측오차 관계','', '주 residual은 관측 선형 경로+Fixed learned we, 비교 오차는 Physics−Baseline squared error. 양의 상관은 residual 큰 곳/날짜에서 Physics가 상대적으로 악화되는 경향이다. 동일 관측값을 공유하고 we가 학습되어 수학적 결합·역인과가 가능하므로 인과 효과가 아니다.','',table([r for r in relation if r['split']=='test'],['ratio','lead','day_corr_residual_vs_pinn_rmse','day_corr_residual_vs_delta_mse','cell_corr_residual_vs_delta_mse','pooled_corr_abs_residual_vs_delta_se']),'', '상위10/25/50%는 각 명시된 split/season/region 내부 |누적 residual| 분위수로 정의한다. cutoff 동률을 모두 포함하므로 실제 비율은 조금 달라질 수 있다. Train/Validation/Test 결과를 분리했고, Test에서 찾은 cutoff는 학습 weight로 적용하지 않았다.','',table([r for r in strata_summary if r['split']=='test' and r['season']=='all' and r['region']=='all'],['ratio','lead','top_fraction','improvement_percent','delta_mse']),'', '계절·해안 비교: strata_summary.csv와 residual_error_strata.csv. Correlation은 기술통계이며 격자·날짜를 독립 표본으로 놓은 유의성 검정은 하지 않았다.','', '## 4.MHW 탐지 오차','', '기존 threshold 및5일 지속 조건,Test 경계 규칙을 그대로 재사용하고 저장된 event flags와 완전히 일치함을 확인했다. 단일 threshold 초과율은 duration event와 별도로 기록했다. 임계값 근처는 관측 threshold±.25K, 고강도는 관측 MHW 중 (T−clim)/(threshold−clim)≥2로 진단용 정의했다.','',table([r for r in mhwsum if r['ratio'] in ['10','50'] and r['lead']=='7' and r['group'] in ['all','MHW','non_MHW','near_above_0to025K','high_intensity_obs_MHW_ratio_ge2']],['ratio','model','group','rmse','bias','pred_below_threshold_fraction']),'', 'mhw_transitions.csv:새FN/회복FN/새FP/제거FP 및 공통TP/FN/FP/TN의 grid-day 수,온도 이동,threshold 거리. 지속 기간 판정 때문에 작은 온도 변화가 여러 날짜의 event flag를 바꿀 수 있다. 임계값0.25K는 기술통계 bin이며 성능을 보고 튜닝한 threshold가 아니다.','', '## 5.Adaptive λ 오프라인 검토','', 'Gradient를 추가 계산하지 않고 저장된384batch를 재사용했다. 후보rho=.05/.10/.25,lambda[.0001,.03],기존warmup을 반영했다. ordered_frozen_batch_EMA는 저장된32batch 순서에서beta=.9를 적용한 민감도 그림이며 실제100-update 간격의 동역학 또는 성능 예측이 아니다. 실제 warmup은 checkpoint epoch를 따른다.','',table([r for r in adsum if r['state']=='best' and r['mode']=='instantaneous'],['ratio','lead','rho','lambda_median','upper_clamp_fraction','greater_than_fixed_fraction','effective_ratio_median','conflict_fraction']),'', '이 결과만으로 최적rho를 선택하지 않았다. 기존 paused Adaptive protocol의rho=.25 및 기타 설정은 변경하지 않았다. 가중치가 커지면 충돌 Gradient도 커질 수 있고, magnitude balancing은 방향을 수정하지 않는다.','', '## 6.Climatology·입력 분포','',table(coverage,['ratio','unique_input_days','empty_doy','singleton_doy','singleton_fraction','feb29_count']),'', '366개 leap-aligned month/day bin과 selected-only periodic linear interpolation을 보존했다. 비어있는 DOY에 Full climatology를 사용하지 않는다. Feb29는bin59(0-based)이며 없는 경우 동일한 주기 보간이다. 육지는0,유효 해양값은finite. Singleton bin은 학습 관측 자체가 평균이 되어 해당 학습 anomaly가0임을 수치검증했다.','',table([r for r in rs if r['variable']=='sst_anom'],['ratio','climatology_daystep_rms','climatology_daystep_abs_p95','climatology_daystep_abs_max','singleton_training_date_fraction']),'',table([r for r in aa if r['variable']=='sst_anom' and r['lead']=='7'],['ratio','split','raw_std','anomaly_std','history_z_std']),'', 'all_input_zscores.csv는19개 동적 입력+3개 정적 채널의|z|>5/10/20빈도. 기존 exhaustive v2 tensor scan을 v3와 통계/날짜/climatology 동일성 확인 후 재사용했으며7 anomaly 채널의 history-weighted 표준편차를 새로 계산해 대조했다. Climatology roughness는 추정 특성이지 참 climatology에 대한 정확도 증거가 아니다. 시기별 분포차에는 온난화/기간구성 등도 포함된다.','', '## 7.통계적 안정성','', 'ΔRMSE=Physics−Baseline. 저장된4000개 circular temporal block 재표본에서 T*−T로 귀무분포를 중심화하고 p=(1+count(|T*−T|≥|T|))/(B+1)로 계산했다. CI에서 p를 역산하지 않았다. 시간 의존성·계절성 하에서 근사 bootstrap 검정이며 유한표본 exact 검정이 아니다. Holm은각 block 길이에서8조건 family에 적용했다.90일 primary,30/180일 민감도.','',table(p90,['ratio','lead','delta_rmse','ci_low','ci_high','p_centered_bootstrap','p_holm_8']),'', 'paired_ratio_contrasts.csv는 같은 날짜·seed·bootstrap draw를 이용한 자료량6쌍×2lead 차이이며12비교 Holm도 제공. seed_uncertainty.csv는3seed의 방향/SD와8가지 exact sign-flip 참고값(최소 양측p=.25)을 제공한다. Temporal CI는 이3개 학습모델에 조건부이며 seed 모집단 불확실성을 포괄하지 않는다.','', 'MHW bootstrap은 원래 연속시계열에서 판정한 event flags의 날짜별 contingency counts를 모델·seed 간 공동 재표본한다. 재표본 block 연결부에서 event를 새로 판정하지 않는다. 이는 grid-day CSI/POD/FAR의 조건부 시간 불확실성이며 독립 event onset/duration bootstrap은 아니다. Metric별8비교 Holm 및3metric×8조건24비교 Holm을 모두 제공한다.','',table([r for r in mb if r['block_days']=='90'],['ratio','lead','metric','delta','ci_low','ci_high','p_holm_8_per_metric','p_holm_24_metrics_conditions']),'', '## 8.후속 물리손실 후보 — 설계만','', '현재 daily loss는 clipping이 없고 mask/scale이 고정일 때 mean_j(r_j²)=mean_j(r_j)²+Var_j(r_j)로 분해된다. 예측 endpoint만 학습하면서 선형 중간경로에도 매일 물리식을 강제하는 것은 누적 변화 오차 외에 일별 residual 변동도 벌점화한다.','', '후보1: 누적 residual R_L=(T_hat_L−T0)−sum_j RHS_j·1day(K), loss mean[(R_L/L)²]/S_RHS. RHS는 기존 일별 forcing·공간차분을 그대로 평가하며 이 식은 새 후보로서 현재 loss와 같지 않다. 기존 daily clipping과 sum은 교환되지 않으므로 clipping/normalization 정책을 사전에 따로 검증해야 한다. 누적 검사가 좋지 않으면 적분형으로 바꾸는 것만으로 해결된다고 주장할 수 없다.','', '후보2: 학습자료에서 정의한 계절/해역 신뢰도 가중치. Validation에서 필요성을 검증해야 하며 Test residual로 weight를 학습하면 안 된다. Predictor에 의존하는 학습된we/예측 residual을 weight로 사용할 때 trivial suppression 및 관측값공유 결합을 점검해야 한다.','', '후보3: 물리항의 적합성 검토(고정1K contrast,기간불변 positivewe,재분석 forcing 및 생략된 과정). 사용 가능한 관측근거와 물리식 검증 없이 새로운 항을 임의로 추가하지 않는다. 이번 작업에서는 모델/loss/climatology 수정이나 어느 후보의 신규 학습도 하지 않았다.','', '## 재현 코드 위치','', '- scripts/cpu_artifact_audit.py:main — 저장필드/체크포인트/원본해시 감사','- scripts/cpu_physics_diagnostics.py:main — native RHS재사용,기간합,zeroRHS기준,회귀검사와오차관계','- scripts/cpu_mhw_statistics.py:main — native event재현,오류분해,centered bootstrap/Holm','- scripts/cpu_offline_adaptive.py:main — frozen gradient 후보/EMA 시뮬레이션','- scripts/cpu_climatology_diagnostics.py:main — DOY/roughness/분포와v2v3동일성','- src/train_hybrid_jeju_forecast.py:738 — 실제 _linear_rhs_per_day','- src/mhw/ocean_stencil.py:21 — 실제 해안 gradient','- src/mhw/mhw_skill.py:98 — 지속기간 처리;128 — mhw_binary_field','- src/mhw/subset_climatology.py:20 — calendar_bins;27 — fit_climatology;60 — anomaly','', '상세 산출물과 source SHA는 analysis_protocol.json,protected_input_hashes.json,code_provenance.json 및 각 phase_status.json에 기록했다.']
 diagnostic_interpretation=['','## 9.수치 기반 핵심 요약','',f'Test 누적 물리 skill이 음수인 조건: {bad}/8. 누적 경로의 오차 상쇄와 실제 누적 변화 적합성은 별개다. 물리식의 누적 적합성이 낮은 경우 단순히 loss를 기간합으로 바꾸는 것만으로 물리적 타당성이 확보된다고 볼 수 없다.']
 t_rel=[r for r in relation if r['split']=='test'];positive=sum(r['day_corr_residual_vs_delta_mse']>0 for r in t_rel)
 diagnostic_interpretation += [f'Test 날짜별 residual–Physics상대오차 상관이 양수인 조건: {positive}/8. 부호/크기가 조건에 따라 다른지는 relationship_summary.csv에 모두 보존했다. 평균 residual 크기만으로 보편적인 신뢰도 weight를 정할 근거로 삼지 않는다.',f'90일 block SST Holm 보정 p<.05 조건 수: {sum(float(r["p_holm_8"])<.05 for r in p90)}/8. 개별CI와 다중비교 결론을 구분한다.','','관심 MHW 두 조건의 event 전환(3seed별 grid-day 수/통계 평균):',table([r for r in transition_summary if r['ratio'] in ['10','50'] and r['lead']=='7' and r['event_transition'] in ['new_FN','recovered_FN','new_FP','removed_FP']],['ratio','lead','event_transition','n','pinn_minus_baseline_temperature_K','near_threshold_abs025K_fraction'])]
 lines+=diagnostic_interpretation
 (OUT/'report_ko.md').write_text('\n'.join(lines)+'\n')
